// Minimal argparse-compatible CLI parser for a parser with:
//   parser.add_argument('--a', type=str, required=True)
//   parser.add_argument('--b', type=str, required=True)
// plus the implicit -h/--help. Replicates the relevant CPython argparse
// behaviors: '--opt value' and '--opt=value' forms, unambiguous long-option
// prefix abbreviation, last-occurrence-wins, error messages on stderr with
// exit code 2, help on stdout with exit code 0.

const LONG_OPTIONS = ['--help', '--a', '--b'];
const REQUIRED = ['--a', '--b'];

// argparse's _negative_number_matcher; tokens matching this are values,
// not options, when no option looks like a negative number.
const NEGATIVE_NUMBER = /^-\d+$|^-\d*\.\d+$/;

function isOptionLike(token) {
  return (
    token.length > 1 &&
    token[0] === '-' &&
    !NEGATIVE_NUMBER.test(token)
  );
}

function usageLine(prog) {
  return `usage: ${prog} [-h] --a A --b B\n`;
}

function errorExit(prog, message) {
  process.stderr.write(usageLine(prog));
  process.stderr.write(`${prog}: error: ${message}\n`);
  process.exit(2);
}

function printHelp(prog) {
  process.stdout.write(
    usageLine(prog) +
      '\n' +
      'options:\n' +
      '  -h, --help  show this help message and exit\n' +
      '  --a A\n' +
      '  --b B\n'
  );
  process.exit(0);
}

export function parseArgs(argv, prog) {
  const values = {};
  const leftovers = [];
  let i = 0;
  let sawDoubleDash = false;

  while (i < argv.length) {
    const token = argv[i];

    if (sawDoubleDash) {
      leftovers.push(token);
      i += 1;
      continue;
    }

    if (token === '--') {
      sawDoubleDash = true;
      i += 1;
      continue;
    }

    if (token.startsWith('--')) {
      const eq = token.indexOf('=');
      const name = eq === -1 ? token : token.slice(0, eq);
      const explicitValue = eq === -1 ? null : token.slice(eq + 1);

      // Exact match wins; otherwise unambiguous prefix abbreviation.
      let match = LONG_OPTIONS.includes(name) ? name : null;
      if (match === null) {
        const candidates = LONG_OPTIONS.filter((opt) => opt.startsWith(name));
        if (candidates.length === 1) {
          match = candidates[0];
        } else if (candidates.length > 1) {
          errorExit(
            prog,
            `ambiguous option: ${name} could match ${candidates.join(', ')}`
          );
        }
      }

      if (match === null) {
        leftovers.push(token);
        i += 1;
        continue;
      }

      if (match === '--help') {
        printHelp(prog);
      }

      // --a / --b take exactly one argument.
      if (explicitValue !== null) {
        values[match] = explicitValue;
        i += 1;
        continue;
      }
      const next = argv[i + 1];
      if (next === undefined || isOptionLike(next)) {
        errorExit(prog, `argument ${match}: expected one argument`);
      }
      values[match] = next;
      i += 2;
      continue;
    }

    if (isOptionLike(token)) {
      if (token === '-h') {
        printHelp(prog);
      }
      leftovers.push(token);
      i += 1;
      continue;
    }

    // No positionals are defined, so any plain token is a leftover.
    leftovers.push(token);
    i += 1;
  }

  // argparse reports missing required arguments before unrecognized ones.
  const missing = REQUIRED.filter((opt) => !(opt in values));
  if (missing.length > 0) {
    errorExit(
      prog,
      `the following arguments are required: ${missing.join(', ')}`
    );
  }

  if (leftovers.length > 0) {
    errorExit(prog, `unrecognized arguments: ${leftovers.join(' ')}`);
  }

  return { a: values['--a'], b: values['--b'] };
}

// Python-repr formatter for the decode() result tuple.
// decode() returns [witver, witprog] where each element is a number or null
// (witprog is a plain array of numbers when present). formatResult renders
// the pair exactly as Python's print() would render the 2-tuple
// (witver, witprog): None for null, integers plain, lists as [a, b, c]
// with ', ' separators, and the tuple itself as (x, y).

function pyRepr(value) {
  if (value === null) {
    return 'None';
  }
  if (Array.isArray(value)) {
    return `[${value.map(pyRepr).join(', ')}]`;
  }
  return String(value);
}

export function formatResult(result) {
  return `(${result.map(pyRepr).join(', ')})`;
}

import { spawnSync } from 'node:child_process';
import { formatResult } from '/output/lib/pyformat.mjs';

let failures = 0;
function check(name, actual, expected) {
  const ok = JSON.stringify(actual) === JSON.stringify(expected);
  if (!ok) {
    failures += 1;
    console.log(`FAIL ${name}\n  expected: ${JSON.stringify(expected)}\n  actual:   ${JSON.stringify(actual)}`);
  } else {
    console.log(`ok   ${name}`);
  }
}

function runCli(args) {
  const r = spawnSync(
    process.execPath,
    ['--input-type=module', '-e',
     `import { parseArgs } from '/output/lib/cli.mjs';\n` +
     `const r = parseArgs(JSON.parse(process.env.CLI_ARGS), 'PROG');\n` +
     `process.stdout.write(JSON.stringify(r) + '\\n');`,
     ...[]],
    { env: { ...process.env, CLI_ARGS: JSON.stringify(args) }, encoding: 'utf8' }
  );
  return { status: r.status, stdout: r.stdout, stderr: r.stderr };
}

const HELP = 'usage: PROG [-h] --a A --b B\n' +
  '\n' +
  'options:\n' +
  '  -h, --help  show this help message and exit\n' +
  '  --a A\n' +
  '  --b B\n';
const USAGE = 'usage: PROG [-h] --a A --b B\n';

// success: --a value --b value
check('basic', runCli(['--a', 'bc', '--b', 'xyz']),
  { status: 0, stdout: '{"a":"bc","b":"xyz"}\n', stderr: '' });
// --a=value form
check('equals form', runCli(['--a=bc', '--b=xyz']),
  { status: 0, stdout: '{"a":"bc","b":"xyz"}\n', stderr: '' });
// unique-prefix abbreviation
check('abbrev', runCli(['--a', '1', '--', '--b', '2']).status === undefined ? null : runCli(['--a', 'x', '--b', 'y']),
  { status: 0, stdout: '{"a":"x","b":"y"}\n', stderr: '' });
// last occurrence wins
check('last wins', runCli(['--a', 'one', '--a', 'two', '--b', 'b']),
  { status: 0, stdout: '{"a":"two","b":"b"}\n', stderr: '' });
// -h
check('-h', runCli(['-h']), { status: 0, stdout: HELP, stderr: '' });
// --help
check('--help', runCli(['--help']), { status: 0, stdout: HELP, stderr: '' });
// --help abbreviation --he
check('--he abbrev', runCli(['--he']), { status: 0, stdout: HELP, stderr: '' });
// missing both
check('missing both', runCli([]),
  { status: 2, stdout: '', stderr: USAGE + 'PROG: error: the following arguments are required: --a, --b\n' });
// missing only --b
check('missing --b', runCli(['--a', 'bc']),
  { status: 2, stdout: '', stderr: USAGE + 'PROG: error: the following arguments are required: --b\n' });
// unrecognized with all required present
check('unrecognized', runCli(['--a', 'bc', '--b', 'xyz', '--extra', 'foo']),
  { status: 2, stdout: '', stderr: USAGE + 'PROG: error: unrecognized arguments: --extra foo\n' });
// required error takes precedence over unrecognized
check('required precedence', runCli(['--extra', 'foo']),
  { status: 2, stdout: '', stderr: USAGE + 'PROG: error: the following arguments are required: --a, --b\n' });
// option value starting with '-' -> expected one argument
check('expected one argument', runCli(['--a', '--b', 'x']),
  { status: 2, stdout: '', stderr: USAGE + 'PROG: error: argument --a: expected one argument\n' });
// missing value at end of argv
check('value missing at end', runCli(['--b', 'x', '--a']),
  { status: 2, stdout: '', stderr: USAGE + 'PROG: error: argument --a: expected one argument\n' });

// pyformat tests
check('fmt nulls', formatResult([null, null]), '(None, None)');
check('fmt v0', formatResult([0, [117, 30, 118, 232, 25, 145, 150, 212, 84, 148, 28, 69, 209, 179, 163, 35, 241, 67, 59, 214]]),
  '(0, [117, 30, 118, 232, 25, 145, 150, 212, 84, 148, 28, 69, 209, 179, 163, 35, 241, 67, 59, 214])');
check('fmt v16', formatResult([16, [117, 30]]), '(16, [117, 30])');
check('fmt v2', formatResult([2, [117, 30, 118, 232, 25, 145, 150, 212, 84, 148, 28, 69, 209, 179, 163, 35]]),
  '(2, [117, 30, 118, 232, 25, 145, 150, 212, 84, 148, 28, 69, 209, 179, 163, 35])');
check('fmt empty list', formatResult([3, []]), '(3, [])');

console.log(failures === 0 ? 'ALL PASS' : `${failures} FAILURES`);
process.exit(failures === 0 ? 0 : 1);
